using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Linq;
using System.Windows.Forms;
namespace Overclock {
 static class Theme {
  public static readonly Color Background=Color.FromArgb(16,18,20),Surface=Color.FromArgb(16,19,21),Raised=Color.FromArgb(32,36,39),Line=Color.FromArgb(64,71,75),Text=Color.FromArgb(245,246,247),Muted=Color.FromArgb(185,192,199),Accent=Color.FromArgb(255,35,60),AccentSoft=Color.FromArgb(230,92,109),Secondary=Color.FromArgb(181,188,197),Primary=Color.FromArgb(139,0,17),PrimaryHover=Color.FromArgb(217,0,25),SelectedSurface=Color.FromArgb(65,14,22),Warning=Color.FromArgb(255,195,56),Cyan=Color.FromArgb(0,195,255),Mint=Color.FromArgb(76,229,170);
  public static GraphicsPath Angular(RectangleF r,float cut){var p=new GraphicsPath();cut=Math.Min(cut,Math.Min(r.Width,r.Height)/3);p.AddPolygon(new[]{new PointF(r.Left+cut,r.Top),new PointF(r.Right-cut,r.Top),new PointF(r.Right,r.Top+cut),new PointF(r.Right,r.Bottom-cut),new PointF(r.Right-cut,r.Bottom),new PointF(r.Left+cut,r.Bottom),new PointF(r.Left,r.Bottom-cut),new PointF(r.Left,r.Top+cut)});return p;}
  static readonly Dictionary<string,Font> faces=new Dictionary<string,Font>();public static Font Face(float size,FontStyle style=FontStyle.Regular){string key=size+"/"+style;Font f;if(!faces.TryGetValue(key,out f)){f=new Font("Segoe UI",size,style);faces[key]=f;}return f;}
  public static GraphicsPath Round(RectangleF r,float radius){var p=new GraphicsPath();float d=radius*2;p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
  public static Button Button(string text,bool primary=false){return new ModernButton{Font=Theme.Face(11),Text=text,Primary=primary,Width=145,Height=38,Margin=new Padding(0,0,10,0)};}
  public static Label Label(string text,int size=10,Color? color=null){return new Label{Text=text,ForeColor=color??Muted,Font=new Font("Segoe UI",Math.Max(10,size)),AutoEllipsis=true};}
  public static void Combo(DarkCombo c){c.BackColor=Raised;c.ForeColor=Text;c.FlatStyle=FlatStyle.Flat;c.DrawMode=DrawMode.OwnerDrawFixed;c.ItemHeight=26;c.Font=Theme.Face(11);if(c.Tag as string=="themed")return;c.Tag="themed";c.DrawItem+=(s,e)=>{if(e.Index<0)return;using(var brush=new SolidBrush((e.State&DrawItemState.Selected)!=0?SelectedSurface:Raised))e.Graphics.FillRectangle(brush,e.Bounds);TextRenderer.DrawText(e.Graphics,c.Items[e.Index].ToString(),c.Font,new Rectangle(e.Bounds.X+8,e.Bounds.Y,e.Bounds.Width-12,e.Bounds.Height),Text,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);};}
  public static DataGridView Grid(params string[] columns){var g=new DarkGrid{Dock=DockStyle.Fill,BackgroundColor=Surface,BorderStyle=BorderStyle.None,GridColor=Line,RowHeadersVisible=false,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AllowUserToResizeRows=false,ReadOnly=true,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,EnableHeadersVisualStyles=false,CellBorderStyle=DataGridViewCellBorderStyle.SingleHorizontal,ColumnHeadersBorderStyle=DataGridViewHeaderBorderStyle.None};g.DefaultCellStyle=new DataGridViewCellStyle{BackColor=Surface,ForeColor=Text,SelectionBackColor=SelectedSurface,SelectionForeColor=Text,Font=Theme.Face(12),Padding=new Padding(10,0,10,0)};g.ColumnHeadersDefaultCellStyle=new DataGridViewCellStyle{BackColor=Raised,ForeColor=Muted,Font=Theme.Face(9,FontStyle.Bold),Padding=new Padding(10,0,10,0)};g.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(27,32,35);g.ColumnHeadersHeight=38;g.RowTemplate.Height=32;foreach(string c in columns){int i=g.Columns.Add(c,c);g.Columns[i].MinimumWidth=c.Length>12?140:90;}return g;}
 }
 sealed class DarkGrid:DataGridView {public DarkGrid(){DoubleBuffered=true;ShowCellToolTips=false;}}
 sealed class ModernButton:Button {
  public bool Primary,Selected;public string NavGlyph;public float NavigationScale;bool hover;public ModernButton(){FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;BackColor=Theme.Background;ForeColor=Theme.Text;Cursor=Cursors.Hand;SetStyle(ControlStyles.UserPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.AllPaintingInWmPaint,true);MouseEnter+=(s,e)=>{hover=true;Invalidate();};MouseLeave+=(s,e)=>{hover=false;Invalidate();};}
  protected override void OnPaint(PaintEventArgs e){e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;bool navigation=NavGlyph!=null;float scale=navigation?(NavigationScale>0?NavigationScale:e.Graphics.DpiX/96):1;bool red=Enabled&&(Primary||Selected);using(var path=Theme.Angular(new RectangleF(.5f,.5f,Width-1,Height-1),7*scale)){using(var b=new LinearGradientBrush(ClientRectangle,!Enabled?Theme.Surface:red?Theme.PrimaryHover:hover?Theme.Line:Theme.Raised,red?Theme.Primary:Theme.Surface,90))e.Graphics.FillPath(b,path);using(var p=new Pen(red?Theme.Accent:Theme.Line))e.Graphics.DrawPath(p,path);}if(navigation){var state=e.Graphics.Save();e.Graphics.ScaleTransform(scale,scale);DrawGlyph(e.Graphics,Height/scale);e.Graphics.Restore(state);}int left=navigation?SidebarPanel.Pixels(SidebarPanel.LabelLeft,scale):12;int right=navigation?SidebarPanel.Pixels(12,scale):12;TextRenderer.DrawText(e.Graphics,Text,Font,new Rectangle(left,0,Math.Max(1,Width-left-right),Height),!Enabled?Theme.Muted:Theme.Text,TextFormatFlags.VerticalCenter|(navigation?TextFormatFlags.Left:TextFormatFlags.HorizontalCenter)|TextFormatFlags.EndEllipsis);if(Focused)ControlPaint.DrawFocusRectangle(e.Graphics,new Rectangle(5,5,Width-10,Height-10));}
  void DrawGlyph(Graphics g,float logicalHeight){int y=(int)(logicalHeight/2);using(var p=new Pen(Theme.Text,1.5f)){if(NavGlyph=="Overview"){for(int i=0;i<3;i++)g.DrawRectangle(p,20+i*6,y+5-i*4,3,7+i*4);}else if(NavGlyph=="Hardware"){g.DrawRectangle(p,18,y-8,17,17);for(int i=0;i<4;i++){g.DrawLine(p,14,y-6+i*4,18,y-6+i*4);g.DrawLine(p,35,y-6+i*4,39,y-6+i*4);}}else if(NavGlyph=="Storage tests"){g.DrawEllipse(p,18,y-9,18,7);g.DrawArc(p,18,y-4,18,7,0,180);g.DrawArc(p,18,y+1,18,7,0,180);g.DrawLine(p,18,y-6,18,y+5);g.DrawLine(p,36,y-6,36,y+5);}else if(NavGlyph=="GPU stress"||NavGlyph=="Compact monitor"){g.DrawRectangle(p,17,y-9,21,15);g.DrawLine(p,27,y+6,27,y+11);g.DrawLine(p,22,y+11,33,y+11);}else if(NavGlyph=="RGB Studio"){g.DrawEllipse(p,18,y-9,18,18);g.DrawEllipse(p,23,y-4,8,8);g.DrawLine(p,16,y+9,38,y-9);}else if(NavGlyph=="Display Studio"){g.DrawRectangle(p,17,y-9,21,15);g.DrawLine(p,27,y+6,27,y+11);g.DrawLine(p,22,y+11,33,y+11);}else if(NavGlyph=="Settings"){g.DrawEllipse(p,17,y-9,20,20);g.DrawEllipse(p,23,y-3,8,8);}else if(NavGlyph=="Logs"){for(int i=0;i<3;i++)g.DrawLine(p,18,y-7+i*7,37,y-7+i*7);}else{g.DrawRectangle(p,20,y-10,15,21);g.DrawLine(p,23,y-3,31,y-3);g.DrawLine(p,23,y+3,31,y+3);}}}
 }
 sealed class HardwareView:UserControl {
  readonly SensorClient client;readonly Dictionary<string,Collector> sources;readonly string category;readonly DataGridView grid=Theme.Grid("Reading","Value","Unit");readonly Timer timer=new Timer{Interval=1500};readonly IdentityBanner banner=new IdentityBanner();readonly SensorGraph history=new SensorGraph{Dock=DockStyle.Fill};readonly DataGridView cores=Theme.Grid("Logical CPU","Load (%)"),summaryGrid=Theme.Grid("System","Detected value");readonly MetricCard storageSummary=new MetricCard();readonly SensorGraph sentHistory=new SensorGraph{Dock=DockStyle.Bottom,Height=245,Accent=Theme.Warning};readonly Queue<float> received=new Queue<float>(),sent=new Queue<float>();DateTime networkStamp;string adapterKey="";string last="";
  public HardwareView(string page,SensorClient sensors,Dictionary<string,Collector> providers){Dock=DockStyle.Fill;BackColor=Theme.Background;category=page;client=sensors;sources=providers;var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=page=="CPU"?3:2,RowCount=1};if(page=="CPU")layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,27));layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,page=="CPU"?38:58));layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,page=="CPU"?35:42));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));if(page=="CPU"){var corePanel=new SectionPanel("Per-core utilization"){Dock=DockStyle.Fill,Margin=new Padding(0,0,12,0)};corePanel.Controls.Add(cores);layout.Controls.Add(corePanel);}var details=new SectionPanel(page=="Inventory"?"Detected components":page+" details"){Dock=DockStyle.Fill,Margin=new Padding(0,0,12,0)};details.Controls.Add(grid);layout.Controls.Add(details);var chart=new SectionPanel(page=="Inventory"?"System summary":page=="Storage"?"Capacity overview":"Live telemetry history"){Dock=DockStyle.Fill,Margin=Padding.Empty};if(page=="Inventory")chart.Controls.Add(summaryGrid);else if(page=="Storage"){storageSummary.Dock=DockStyle.Fill;chart.Controls.Add(storageSummary);}else{chart.Controls.Add(history);if(page=="Network")chart.Controls.Add(sentHistory);}layout.Controls.Add(chart);banner.Caption=page;banner.Height=170;banner.Model="Detecting hardware";banner.Summary="Unsupported readings are marked unavailable";Controls.Add(layout);Controls.Add(new Panel{Dock=DockStyle.Top,Height=14});Controls.Add(banner);timer.Tick+=(s,e)=>RefreshData();Disposed+=(s,e)=>timer.Dispose();timer.Start();RefreshData();}
  void RefreshBanner(){sources["Identity"].Request(false);string raw=sources[category=="Memory"?"CPU":category].Value;HardwareIdentity identity;try{identity=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<HardwareIdentity>(sources["Identity"].Value);}catch{identity=new HardwareIdentity();}string model=category=="CPU"?raw.Split('\n').Skip(1).FirstOrDefault()??"Detecting processor":category=="GPU"?raw.Split('\n').FirstOrDefault()??"Detecting graphics":category=="Memory"?"System memory":category=="Storage"?"System storage":category=="Network"?raw.Split(new[]{"  "},StringSplitOptions.None)[0]:"Detected system hardware";string art=category=="CPU"?DashboardArt.Cpu(identity.CpuVendor):category=="GPU"?DashboardArt.Gpu(model.Trim(),identity.Gpus):category=="Memory"?"memory":null;string summary="Live readings · Unsupported values remain unavailable";if(category=="CPU"||category=="GPU")summary=string.Join("   ·   ",raw.Split('\n').Where(v=>v.StartsWith("CPU load")||v.StartsWith("Load ")||v.StartsWith("Temperature")||v.StartsWith("Power ")||v.StartsWith("Clock ")).Take(4).Select(v=>System.Text.RegularExpressions.Regex.Replace(v.Trim(),@"\s+"," ")).ToArray());if(category=="Memory")summary=raw.Split('\n').FirstOrDefault(v=>v.StartsWith("RAM"))??"Memory capacity unavailable";if(category=="Storage"){sources["Capacity"].Request(false);try{var c=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<StorageCapacity>(sources["Capacity"].Value);summary=StorageFormat.Size(c.PhysicalBytes)+" total · "+StorageFormat.Size(c.UsedBytes)+" used · "+StorageFormat.Size(c.FreeBytes)+" free";art=DashboardArt.Storage(c);}catch{}}if(category=="Network"){var m=System.Text.RegularExpressions.Regex.Match(raw,@"Type=([^;]+);Physical=([^;]+);State=([^;]+)");if(m.Success)art=DashboardArt.Network(m.Groups[1].Value,m.Groups[3].Value,m.Groups[2].Value=="True");summary=raw.Split('\n')[0].Split('[')[0].Trim();}banner.Aside=null;if(category=="CPU"||category=="GPU"){var metric=System.Text.RegularExpressions.Regex.Match(raw,category=="CPU"?@"CPU load\s+([^\r\n]+)":@"Load\s+([^\r\n]+)");var temp=client.Snapshot.Sensors.FirstOrDefault(v=>v.Id.IndexOf(category.ToLowerInvariant(),StringComparison.OrdinalIgnoreCase)>=0&&v.Type=="Temperature"&&v.Value.HasValue);banner.Aside=(metric.Success?metric.Groups[1].Value:"N/A")+" load"+(temp==null?"":"\n"+temp.Value.Value.ToString("0")+" °C");}banner.Model=model.Trim();banner.Summary=summary;banner.ArtKey=art;banner.Invalidate();if(category=="Inventory"){var facts=new List<object[]>();facts.Add(new object[]{"Windows version",Environment.OSVersion.VersionString});facts.Add(new object[]{"System architecture",Environment.Is64BitOperatingSystem?"64-bit":"32-bit"});facts.Add(new object[]{"Logical processors",Environment.ProcessorCount});facts.Add(new object[]{"CPU vendor",identity.CpuVendor??"Unavailable"});foreach(var adapter in identity.Gpus)facts.Add(new object[]{"Graphics adapter",adapter.Name});facts.Add(new object[]{"Sensor channels",client.Snapshot.Sensors.Count});GridData.Apply(summaryGrid,facts);}if(category=="Storage"){try{storageSummary.Capacity=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<StorageCapacity>(sources["Capacity"].Value);storageSummary.ArtKey=DashboardArt.Storage(storageSummary.Capacity);storageSummary.Set("Storage",StorageFormat.Size(storageSummary.Capacity.PhysicalBytes),"installed internal storage","Physical drives","Mounted-volume capacity","",-1,"",new float[0]);}catch{}}
string filter=category=="Memory"?"ram":category.ToLowerInvariant();var sensor=client.Snapshot.Sensors.FirstOrDefault(v=>v.Id.IndexOf(filter,StringComparison.OrdinalIgnoreCase)>=0&&v.Type=="Load"&&v.Value.HasValue);System.Collections.Generic.Queue<float> queue;history.Values=sensor!=null&&client.History.TryGetValue(sensor.Id,out queue)?queue.ToArray():new float[0];history.Title=sensor==null?"History unavailable for this provider":sensor.Hardware+" · "+sensor.Name+" (%)";history.Accent=category=="GPU"?Theme.Cyan:category=="Memory"||category=="Network"?Theme.Mint:Theme.Accent;if(category=="Network"){string first=raw.Split('\n')[0];string adapter=first.Split(new[]{"  "},StringSplitOptions.None)[0];if(adapterKey!=adapter){adapterKey=adapter;received.Clear();sent.Clear();}var match=System.Text.RegularExpressions.Regex.Match(first,@"RX ([0-9.]+) KiB/s\s+TX ([0-9.]+)");if(networkStamp!=sources["Network"].Updated&&match.Success){networkStamp=sources["Network"].Updated;received.Enqueue(float.Parse(match.Groups[1].Value,System.Globalization.CultureInfo.InvariantCulture));sent.Enqueue(float.Parse(match.Groups[2].Value,System.Globalization.CultureInfo.InvariantCulture));while(received.Count>120)received.Dequeue();while(sent.Count>120)sent.Dequeue();}history.Title="Receive · KiB/s · "+adapter;history.Values=received.ToArray();history.Accent=Theme.Cyan;sentHistory.Title="Send · KiB/s · "+adapter;sentHistory.Values=sent.ToArray();sentHistory.Invalidate();}history.Invalidate();if(category=="CPU"){sources["Core load"].Request(false);var rows=System.Text.RegularExpressions.Regex.Matches(sources["Core load"].Value,@"(?m)^\s*(\d+|_Total)\s+(\d+)\s*$").Cast<System.Text.RegularExpressions.Match>().ToArray();while(cores.Rows.Count>rows.Length)cores.Rows.RemoveAt(cores.Rows.Count-1);for(int i=0;i<rows.Length;i++){if(i>=cores.Rows.Count)cores.Rows.Add();cores.Rows[i].Cells[0].Value=rows[i].Groups[1].Value;cores.Rows[i].Cells[1].Value=rows[i].Groups[2].Value;}}}
  void RefreshData(){RefreshBanner();string key=category=="Memory"?"CPU":category;Collector c;if(sources.TryGetValue(key,out c))c.Request(false);if(category=="Memory"||category=="Inventory")sources["Inventory"].Request(false);if(category=="Storage")sources["Disk activity"].Request(false);string raw=c==null?"":c.Display;string filter=category=="CPU"?"cpu":category=="GPU"?"gpu":category=="Memory"?"ram":category=="Storage"?"storage":"";var sensors=client.Snapshot.Sensors.Where(v=>filter!=""&&v.Id.IndexOf(filter,StringComparison.OrdinalIgnoreCase)>=0).ToList();string signature=raw+string.Join("",sensors.Select(v=>v.Id+v.Value).ToArray())+(category=="Memory"?sources["Inventory"].Display:"");if(last==signature)return;last=signature;var rows=new List<object[]>();if(category=="Network"){foreach(string line in raw.Split('\n')){var match=System.Text.RegularExpressions.Regex.Match(line,@"^(.*?)\s+RX ([0-9.]+) KiB/s\s+TX ([0-9.]+) KiB/s\s+\[Type=([^;]+);Physical=([^;]+);State=([^;]+);Route=([^\]]+)\]");if(!match.Success)continue;rows.Add(new object[]{"Adapter",match.Groups[1].Value.Trim(),""});rows.Add(new object[]{"Receiving",match.Groups[2].Value,"KiB/s"});rows.Add(new object[]{"Sending",match.Groups[3].Value,"KiB/s"});rows.Add(new object[]{"Interface type",match.Groups[4].Value,""});rows.Add(new object[]{"Physical adapter",match.Groups[5].Value,""});rows.Add(new object[]{"Operational state",match.Groups[6].Value,""});rows.Add(new object[]{"Routing",match.Groups[7].Value,""});}}else if(category=="Storage"){foreach(string line in raw.Split('\n').Where(l=>l.StartsWith("Disk #"))){var p=line.Split('|');rows.Add(new object[]{p[0].Trim()+" · "+p[1].Trim(),p.Length>3?p[3].Trim():"—",p.Length>4?p[4].Trim():""});if(p.Length>6)rows.Add(new object[]{"  Native serial",p[6].Replace("Native serial:","").Trim(),""});}}else foreach(string line in raw.Split('\n').Where(l=>!string.IsNullOrWhiteSpace(l))){if(category=="Memory"&&!line.StartsWith("RAM"))continue;var pieces=new System.Text.RegularExpressions.Regex(@"\s{2,}").Split(line.Trim(),2);rows.Add(new object[]{pieces.Length>1?pieces[0]:"Device",pieces.Length>1?pieces[1]:line.Trim(),""});}foreach(var v in sensors)rows.Add(new object[]{(category=="Memory"?v.Hardware+" · ":"")+v.Name,v.Value.HasValue?v.Value.Value.ToString("0.##"):"—",Unit(v.Type)});if(category=="Memory"){int module=0;foreach(System.Text.RegularExpressions.Match m in System.Text.RegularExpressions.Regex.Matches(sources["Inventory"].Value,@"Manufacturer\s*:\s*([^\r\n]+)\s*PartNumber\s*:\s*([^\r\n]+)\s*Capacity\s*:\s*([^\r\n]+)\s*Speed\s*:\s*([^\r\n]+)")){module++;rows.Add(new object[]{"Module "+module,m.Groups[2].Value.Trim(),""});rows.Add(new object[]{"  Manufacturer",m.Groups[1].Value.Trim(),""});double bytes;if(double.TryParse(m.Groups[3].Value.Trim(),out bytes))rows.Add(new object[]{"  Capacity",(bytes/1073741824).ToString("0.#"),"GiB"});rows.Add(new object[]{"  Frequency",m.Groups[4].Value.Trim(),"MHz"});}}if(rows.Count==0)rows.Add(new object[]{"Provider status",raw==""?"Waiting for supported readings":raw,""});GridData.Apply(grid,rows);}
  internal static string Unit(string type){switch(type){case "Temperature":return "°C";case "Clock":return "MHz";case "Load":return "%";case "Power":return "W";case "Voltage":return "V";case "Fan":return "RPM";case "Data":return "GiB";case "SmallData":return "MiB";case "Throughput":return "B/s";default:return type;}}
 }
}







